import{_ as i,C as n,o as l,c as p,aj as r,G as a,j as e,a as s}from"./chunks/framework.BwH0p-pt.js";const y=JSON.parse('{"title":"Import","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/data-transfer/import.md","filePath":"3.0/data-transfer/import.md","lastUpdated":1785836850000}'),d={name:"3.0/data-transfer/import.md"};function u(c,t,g,m,h,f){const o=n("ImagePopup");return l(),p("div",null,[t[0]||(t[0]=r('<h1 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h1><p>Bulk import is a feature that allows users to import large quantities of data into a system quickly and efficiently. It simplifies the process and saves time by not having to add each piece of information one by one.</p><p>The feature works differently for each system and has a vast variety of use cases across many industries as well as <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>.</p><h2 id="what-you-can-import-in-3-0" tabindex="-1">What you can import in 3.0 <a class="header-anchor" href="#what-you-can-import-in-3-0" aria-label="Permalink to &quot;What you can import in 3.0&quot;">​</a></h2><p>Imports used to cover products and categories. UnoPim 3.0 lets you import your whole catalog structure and even your team setup:</p><table tabindex="0"><thead><tr><th>Area</th><th>Import types</th></tr></thead><tbody><tr><td><strong>Catalog data</strong></td><td>Products, Categories, Product Associations</td></tr><tr><td><strong>Catalog structure</strong></td><td>Attributes, Attribute Options, Attribute Groups, Attribute Families, Category Fields, Association Types</td></tr><tr><td><strong>Store setup</strong></td><td>Locales, Channels, Currencies</td></tr><tr><td><strong>Team</strong></td><td>Roles, Users</td></tr></tbody></table><p>Every type comes with a downloadable sample file showing the expected columns, and every type supports localized values — a label column per language, so you can load names in all your languages in one file.</p>',7)),a(o,{src:"/assets/3.0/images/data-transfer/import-types.png",alt:"Import type selection"}),t[1]||(t[1]=e("h3",{id:"steps-to-add-bulk-import-in-unopim",tabindex:"-1"},[s("Steps to add Bulk Import in UnoPim "),e("a",{class:"header-anchor",href:"#steps-to-add-bulk-import-in-unopim","aria-label":'Permalink to "Steps to add Bulk Import in UnoPim"'},"​")],-1)),t[2]||(t[2]=e("p",null,[e("strong",null,"Step 1:"),s(" Go to the Admin panel of UnoPim and click on "),e("strong",null,"Data Transfer → Imports"),s(" in the sidebar then click the "),e("strong",null,"Create Import"),s(" button.")],-1)),a(o,{src:"/assets/3.0/images/data-transfer/import-listing.png",alt:"Import Listing"}),t[3]||(t[3]=r("<p><strong>Step 2:</strong> Under general configurations add the below fields:</p><ol><li><p><strong>Code -</strong> Enter the code of your Import process.</p></li><li><p><strong>Type -</strong> Select what you want to import — any of the types listed above, from Products to Users.</p></li><li><p><strong>File / Images –</strong> a combined panel covering both the data file and any product images the file references:</p><ul><li><strong>File *</strong> – drag a <strong>CSV / XLSX / XLS</strong> file onto the upload area (<em>&quot;Click to upload or drag and drop&quot;</em>) or click to browse. Allowed file types are shown under the label.</li><li><strong>Download {Type} Sample CSV</strong> – link that downloads the sample file for the Type you selected (e.g., <em>&quot;Download Categories Sample CSV&quot;</em> when Type is Categories). Use it to confirm the expected column layout before you upload your own file.</li><li><strong>Images → Path</strong> – the two-part path UnoPim uses to locate product images: <ul><li>The prefix is locked to <code>storage/app/public/</code>.</li><li>The editable suffix defaults to something like <code>import-images/my-products</code>.</li><li>Click <strong>Upload Images to set Path</strong> to upload an images folder; UnoPim saves it under the prefix and fills the suffix in for you automatically.</li></ul></li><li>Helper text under the field: <em>&quot;Place images in <code>storage/app/public/</code>. For images at <code>storage/app/public/import-images</code>, include <code>import-images/</code> in the path and use only the file name in the import file.&quot;</em></li></ul></li><li><p><strong>Action –</strong> Select Create/Update or Delete from the Settings panel to control whether matching rows are upserted or removed.</p></li><li><p><strong>Validation Strategy –</strong> Choose <strong>Skip Errors</strong> or <strong>Stop on Errors</strong> to decide how the importer reacts when a row fails validation.</p></li><li><p><strong>Allowed Errors –</strong> Maximum number of row-level errors the import tolerates before halting. Default: <strong><code>10</code></strong>.</p></li><li><p><strong>Field Separator –</strong> The character that separates columns in the CSV file. Default: <strong><code>;</code></strong> (semicolon). Only used for CSV files.</p></li></ol><p>Now, click on <strong>Save Import</strong> button.</p>",3)),a(o,{src:"/assets/3.0/images/data-transfer/create-import-form.png",alt:"Create Import Form"}),t[4]||(t[4]=r('<p>The create import form has a two-panel layout:</p><ul><li><strong>General panel (left)</strong> — Code, Type, plus a combined <strong>File / Images</strong> block with the file upload area, the <em>Download {Type} Sample CSV</em> link, and the <strong>Images → Path</strong> field with its <em>Upload Images to set Path</em> button.</li><li><strong>Settings panel (right)</strong> — Action (Create/Update), Validation Strategy (Stop on Errors / Skip Errors), Allowed Errors (default <code>10</code>), Field Separator (default <code>;</code>).</li></ul><h3 id="drag-and-drop-file-upload" tabindex="-1">Drag-and-Drop File Upload <a class="header-anchor" href="#drag-and-drop-file-upload" aria-label="Permalink to &quot;Drag-and-Drop File Upload&quot;">​</a></h3><p>UnoPim v2.0 supports <strong>Drag-and-Drop File Upload</strong> for import files. The upload area displays <strong>&quot;Click to upload or drag and drop&quot;</strong> with supported file types (CSV, XLSX, XLS). You can drag a file directly from your file manager onto the dashed upload area.</p><h3 id="dynamic-import-job-filters" tabindex="-1">Dynamic Import Job Filters <a class="header-anchor" href="#dynamic-import-job-filters" aria-label="Permalink to &quot;Dynamic Import Job Filters&quot;">​</a></h3><p>Import jobs support <strong>dynamic filters</strong> that allow you to configure advanced filtering conditions for your import data. This helps you control exactly which records get imported based on specific criteria.</p><p><strong>Step 3:</strong> From the import listing, click the <strong>Import</strong> action icon (play icon) on the row of the import you want to run. This opens the execution page, which shows a summary of the import configuration:</p><ul><li><strong>Import Profile</strong> — The import code</li><li><strong>File Path</strong> — The uploaded file location</li><li><strong>Action Mode</strong> — Create/Update or Delete</li></ul><p>Click the <strong>Import Now</strong> button to start processing. UnoPim queues the job and redirects you to the <strong>Job Tracker</strong> detail view for that job.</p><h2 id="import-export-tracker" tabindex="-1">Import/Export Tracker <a class="header-anchor" href="#import-export-tracker" aria-label="Permalink to &quot;Import/Export Tracker&quot;">​</a></h2><p><strong>Step 4:</strong> The Job Tracker detail page shows the step pipeline in real time. If validation catches errors, the page surfaces them with row numbers and the exact field that failed, plus a <strong>Download Full Report</strong> button:</p>',11)),a(o,{src:"/assets/3.0/images/data-transfer/import-progress.png",alt:"Import detail page — validation errors"}),t[5]||(t[5]=r('<p>The tracker shows a <strong>step pipeline</strong> with visual progress indicators:</p><table tabindex="0"><thead><tr><th>Step</th><th>Description</th></tr></thead><tbody><tr><td><strong>Queued</strong></td><td>Job is in the queue waiting to be processed</td></tr><tr><td><strong>Validating</strong></td><td>File is being validated against import rules</td></tr><tr><td><strong>Importing</strong></td><td>Records are being created/updated in the database</td></tr><tr><td><strong>Indexing</strong></td><td>Elasticsearch indexes are being updated</td></tr><tr><td><strong>Complete</strong></td><td>Import finished successfully</td></tr></tbody></table><p>Each step shows a green checkmark when completed. Below the pipeline you can see:</p><ul><li><strong>Success/Error message</strong> — Whether the job completed or failed, with details</li><li><strong>Records Created / Updated / Deleted</strong> — Exact counts of what changed</li><li><strong>Total Duration</strong> — How long the import took</li><li><strong>Download log</strong> — Download the full import log file</li><li><strong>Error details</strong> — If validation fails, you see the specific errors (e.g., &quot;Required columns not found: code&quot;)</li></ul><h3 id="pause-resume-and-cancel-controls" tabindex="-1">Pause, Resume, and Cancel Controls <a class="header-anchor" href="#pause-resume-and-cancel-controls" aria-label="Permalink to &quot;Pause, Resume, and Cancel Controls&quot;">​</a></h3><p>During an active import, <strong>job control buttons</strong> appear in the tracker:</p><ul><li><strong>Pause</strong> — Temporarily halt an in-progress import. The job state is preserved and can be resumed later.</li><li><strong>Resume</strong> — Continue a paused import from where it left off.</li><li><strong>Cancel</strong> — Stop an import entirely. Cancelled jobs cannot be resumed.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The pause and resume feature is especially useful for large imports. You can pause a job during peak hours and resume it during off-peak times.</p></div><p>Also you can run the below command in the root of your UnoPim to process the import queue:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:listen</span></span></code></pre></div><p>So by the above steps you can easily create Import Data in UnoPim.</p>',11))])}const k=i(d,[["render",u]]);export{y as __pageData,k as default};
